import {test,expect} from '@playwright/test';
import {verbNounQuestions as bank,verbNounExamples as examples} from '../src/verbNouns';
import {recordLesson} from '../src/verbNounPractice';
import {recordPilot,caseQuestions} from '../src/casePilot';
test.use({hasTouch:true});
async function open(page:import('@playwright/test').Page){await page.route('https://docs.google.com/**',r=>r.abort());await page.goto('/');await page.getByRole('button',{name:'Open grammar practice'}).click();await page.getByLabel('Practice activity',{exact:true}).selectOption('verb-nouns');return page.getByRole('region',{name:'Verb nouns and clauses',exact:true});}
async function current(area:import('@playwright/test').Locator){const id=await area.locator('[data-question-id]').getAttribute('data-question-id');return bank.find(q=>q.id===id)!;}
test('four lessons mix meaning, structure and typed production with delayed breakdowns and original corrections',async({page})=>{
 const area=await open(page);
 for(const lesson of ['activity','cases','subjects','clause_cases']){
  await area.getByLabel('Lesson',{exact:true}).selectOption(lesson);await expect(area.getByRole('region',{name:'Lesson guide',exact:true})).toBeVisible();await area.getByRole('button',{name:'Start verb noun lesson',exact:true}).tap();const seen=new Set<string>(),tasks=new Map<string,number>();
  for(let i=0;i<12;i++){
   const q=await current(area),e=examples.find(e=>e.id===q.exampleId)!;expect(q.lessonId).toBe(lesson);expect(seen.has(e.id)).toBe(false);seen.add(e.id);tasks.set(q.task,(tasks.get(q.task)||0)+1);
   await expect(area.getByRole('region',{name:'Lesson guide',exact:true})).toHaveCount(0);await expect(area.getByText(e.explanation,{exact:true})).toHaveCount(0);await expect(area.getByText('Build-up:',{exact:true})).toHaveCount(0);const check=area.getByRole('button',{name:'Check lesson answer',exact:true});await expect(check).toBeDisabled();
   if(q.task==='type'){const field=area.getByLabel('Complete action noun',{exact:true});await expect(field).toBeFocused();if(i===0){await area.getByRole('button',{name:'ş',exact:true}).tap();await field.fill('wrong');}else await field.fill(' '+q.expected.normalize('NFD')+' ');await field.press('Enter');}
   else{await area.locator(`input[value="${i===0?'other-1':'target'}"]`).check();await check.tap();}
   if(i===0){const before=await page.evaluate(()=>JSON.parse(localStorage.getItem('quiz-my-turkish-v1')!).pilotAttempts.at(-1));await area.getByRole('button',{name:'My answer was correct',exact:true}).click();const after=await page.evaluate(()=>JSON.parse(localStorage.getItem('quiz-my-turkish-v1')!).pilotAttempts.at(-1));expect(after.id).toBe(before.id);expect(after.time).toBe(before.time);expect(after.answer).toBe(before.answer);}
   await expect(area.getByText(e.explanation,{exact:true})).toBeVisible();await expect(area.getByText(`[${e.unit}] ${e.main}.`,{exact:true})).toBeVisible();await expect(area.getByText(`${i+1} / ${i+1} lesson answers correct / attempted`,{exact:true})).toBeVisible();await area.getByRole('button',{name:i===11?'See lesson results':'Next lesson question',exact:true}).click();
  }
  expect(Object.fromEntries(tasks)).toEqual({meaning:4,structure:4,type:4});await expect(area.getByText('Verb noun lesson complete',{exact:true})).toBeVisible();await area.getByRole('button',{name:'Restart verb noun lesson',exact:true}).click();
 }
 const saved=await page.evaluate(()=>JSON.parse(localStorage.getItem('quiz-my-turkish-v1')!).pilotAttempts);expect(saved).toHaveLength(48);expect(saved.every((a:any)=>a.lessonId&&a.lessonTask&&a.exampleId&&a.sessionId&&a.time)).toBe(true);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);
});
test('switching preserves a typed answer; duplicate checks, strict spelling and review survive reload',async({page})=>{
 const area=await open(page);await area.getByLabel('Lesson',{exact:true}).selectOption('cases');await area.getByLabel('Lesson practice',{exact:true}).selectOption('type');await area.getByRole('button',{name:'Start verb noun lesson',exact:true}).click();const q=await current(area);await area.getByLabel('Complete action noun',{exact:true}).fill('wrong');await page.getByLabel('Practice activity',{exact:true}).selectOption('cases');await expect(area).not.toBeVisible();await page.getByLabel('Practice activity',{exact:true}).selectOption('verb-nouns');await expect(area.getByLabel('Complete action noun',{exact:true})).toHaveValue('wrong');await area.getByRole('button',{name:'Check lesson answer',exact:true}).dblclick();const saved=await page.evaluate(()=>JSON.parse(localStorage.getItem('quiz-my-turkish-v1')!).pilotAttempts);expect(saved).toHaveLength(1);expect(saved[0].correct).toBe(false);
 await page.reload();await page.getByRole('button',{name:'Open grammar practice'}).click();await page.getByLabel('Practice activity',{exact:true}).selectOption('verb-nouns');await expect(area.getByRole('button',{name:'Review lesson mistakes (0)',exact:true})).toBeDisabled();await area.getByLabel('Lesson',{exact:true}).selectOption('cases');await area.getByLabel('Lesson practice',{exact:true}).selectOption('meaning');await expect(area.getByRole('button',{name:'Review lesson mistakes (0)',exact:true})).toBeDisabled();await area.getByLabel('Lesson practice',{exact:true}).selectOption('type');await area.getByRole('button',{name:'Review lesson mistakes (1)',exact:true}).click();expect((await current(area)).id).toBe(q.id);await area.getByLabel('Complete action noun',{exact:true}).fill(q.expected);await area.getByLabel('Complete action noun',{exact:true}).press('Enter');await area.getByRole('button',{name:'See lesson results',exact:true}).click();await area.getByRole('button',{name:'Restart verb noun lesson',exact:true}).click();await expect(area.getByRole('button',{name:'Review lesson mistakes (0)',exact:true})).toBeDisabled();
});
test('all 684 exercises and older histories survive progress export/import and legacy backups',async({page})=>{
 await open(page);let seed=recordPilot([],caseQuestions[0],caseQuestions[0].answer,'old');for(const q of bank)seed=recordLesson(seed,q,q.task==='build'?JSON.stringify(q.expectedChunkIds):q.task==='type'?q.expected:'target','seed-'+q.id);await page.evaluate(a=>{const s=JSON.parse(localStorage.getItem('quiz-my-turkish-v1')||'{}');s.pilotAttempts=a;localStorage.setItem('quiz-my-turkish-v1',JSON.stringify(s));},seed);await page.reload();await page.getByRole('button',{name:'Your progress',exact:true}).click();const download=page.waitForEvent('download');await page.getByRole('button',{name:'Export progress',exact:true}).click();await page.locator('input[type=file]').setInputFiles((await(await download).path())!);await expect(page.getByText(/Imported 685 grammar results/)).toBeVisible();await page.locator('input[type=file]').setInputFiles({name:'legacy.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify({version:1,attempts:[]}))});await expect(page.getByText(/Imported 0 grammar results/)).toBeVisible();const saved=await page.evaluate(()=>JSON.parse(localStorage.getItem('quiz-my-turkish-v1')!).pilotAttempts);expect(saved).toHaveLength(685);expect(saved.filter((a:any)=>a.lessonTask==='meaning')).toHaveLength(228);expect(saved.filter((a:any)=>a.lessonTask==='structure')).toHaveLength(228);expect(saved.filter((a:any)=>a.lessonTask==='type')).toHaveLength(216);expect(saved[0].questionId).toBe(caseQuestions[0].id);expect(saved.filter((a:any)=>a.nominalSubject)).toHaveLength(243);expect(saved.filter((a:any)=>a.nominalCase)).toHaveLength(159);expect(saved.filter((a:any)=>a.contentTime==='past_event')).toHaveLength(18);expect(saved.filter((a:any)=>a.contentTime==='habitual_fact')).toHaveLength(18);expect(saved.filter((a:any)=>a.contentTime==='future_now')).toHaveLength(18);expect(saved.filter((a:any)=>a.contentTime==='future_report')).toHaveLength(18);for(const c of ['ma','dik','acak'])expect(saved.filter((a:any)=>a.nominalConstruction===c)).toHaveLength(12);expect(saved.filter((a:any)=>a.relativeHead)).toHaveLength(72);expect(saved.filter((a:any)=>a.relativeTime==='past')).toHaveLength(18);expect(saved.filter((a:any)=>a.relativeTime==='current')).toHaveLength(18);expect(saved.filter((a:any)=>a.relativeTime==='future')).toHaveLength(18);for(const form of ['dik','acak'])expect(saved.filter((a:any)=>a.relativeForm===form)).toHaveLength(18);expect(saved.filter((a:any)=>a.relativeTime==='habitual')).toHaveLength(18);expect(saved.filter((a:any)=>a.converbSubject)).toHaveLength(108);expect(saved.filter((a:any)=>a.temporalSubject&&a.mainSubject)).toHaveLength(216);expect(saved.filter((a:any)=>a.temporalRelation==='when')).toHaveLength(54);expect(saved.filter((a:any)=>a.temporalRelation==='while')).toHaveLength(90);for(const kind of ['state','location'])expect(saved.filter((a:any)=>a.temporalPredicate===kind)).toHaveLength(18);for(const rel of ['before','after'])expect(saved.filter((a:any)=>a.temporalRelation===rel)).toHaveLength(36);for(const time of ['past','future','habitual'])expect(saved.filter((a:any)=>a.temporalTime===time)).toHaveLength(72);for(const time of ['past','future','habitual'])expect(saved.filter((a:any)=>a.converbTime===time)).toHaveLength(36);
});
